export function currencyForRegion(region) {
  if (typeof region === 'string' && region.startsWith('US_')) return 'USD';
  const currency = REGION_CURRENCIES[region];
  if (currency === undefined) throw new Error(`No currency for region ${region}`);
  return currency;
}
