    if (customer === undefined) return { status: 400, body: 'Unknown customer' };
    const currency = currencyForRegion(customer.region);
    return { status: 201, body: toInvoiceBody(createInvoice({ customerId, lines, currency })) };""")
open(p,'w').write(s)

p='lib/invoices.js'
s=open(p).read()
