    handle({ method: 'POST', path: '/invoices', body: { customerId, lines, ...extra } }).body.currency;
  assert.equal(currencyFor('cus_003'), 'EUR');
  assert.equal(currencyFor('cus_004'), 'GBP');
  assert.equal(currencyFor('cus_002'), 'USD');
  assert.equal(currencyFor('cus_005'), 'USD');
  assert.equal(currencyFor('cus_003', { currency: 'USD' }), 'EUR');
});
'''
